/* Tests for input-core.js: the UTF-8 pitfalls table of the research memo
 * (02_utf8_pitfalls.md section 1), newline and BOM options, the hex reader
 * (03_hex_and_cli.md section 1.2, rule B), code point classification and the
 * URL fragment. No digest is written by hand: every expected hash is produced
 * at test time by node:crypto from Buffer.from(string, 'utf8'), and the Day117
 * values come from test/vectors/day117-chain-vectors.json (generated by Python
 * outside this repository). Non-ASCII sample text is written with escapes. */
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const input = require('../input-core.js');
const chainVectors = require('./vectors/day117-chain-vectors.json');

const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const hex = bytes => Buffer.from(bytes).toString('hex');
const utf8 = text => Buffer.from(text, 'utf8');
const codePoints = text => Array.from(text, ch => ch.codePointAt(0));
const access = chainVectors.find(vector => vector.id === 'access');
const seedText = access.headers.join('\n');

/* Rows of the pitfalls table (memo section 1). The raw-byte row 0x7b is covered
 * by the hex tests below. */
const PITFALL_ROWS = [
  '7b', '{', 'A', '\uff21', 'a', '\u0430',
  '\u304c', '\u304b\u3099', '\u00e9', 'e\u0301',
  '\u2460', '1', '\u337b', '\u5e73\u6210',
  '\u2764', '\u2764\ufe0f',
  '\u{1f468}\u200d\u{1f469}\u200d\u{1f467}', '\u{1f468}\u{1f469}\u{1f467}',
  'ab', 'a\u200bb', 'abc', '\ufeffabc',
  'a\nb', 'a\r\nb', 'a\rb', 'abc\n', 'abc\r\n',
  'a b', 'a\u3000b', 'a\u00a0b',
  '\ud800', 'a\ud800b', '\ufffd',
  'a\tb', 'abc ', ''
];

test('UTF-8 table: encodeText reproduces Buffer.from(s, "utf8") byte for byte and hash for hash', () => {
  for (const text of PITFALL_ROWS) {
    const result = input.encodeText(text);
    const reference = utf8(text);
    assert.equal(result.text, text, JSON.stringify(text));
    assert.equal(hex(result.bytes), hex(reference), JSON.stringify(text));
    assert.equal(sha256(result.bytes), sha256(reference), JSON.stringify(text));
    assert.equal(result.stats.byteCount, Buffer.byteLength(text, 'utf8'));
    assert.equal(result.stats.utf16Units, text.length);
    assert.equal(result.stats.codePoints, codePoints(text).length);
    assert.deepEqual(result.chars.map(c => c.cp), codePoints(text));
    assert.deepEqual(result.chars.map(c => c.index), result.chars.map((c, i) => i));
    let offset = 0;
    for (const c of result.chars) {
      assert.equal(c.start, offset);
      assert.equal(hex(result.bytes.subarray(c.start, c.start + c.length)), hex(utf8(c.char)));
      offset += c.length;
    }
    assert.equal(offset, result.bytes.length);
  }
});

test('UTF-8 table: look-alike pairs end in different byte lengths, invisible characters stay in the bytes', () => {
  const bytesOf = text => input.encodeText(text).bytes;
  assert.ok(bytesOf('\u304c').length < bytesOf('\u304b\u3099').length);
  assert.notEqual(sha256(bytesOf('\u304c')), sha256(bytesOf('\u304b\u3099')));
  assert.ok(bytesOf('\u00e9').length < bytesOf('e\u0301').length);
  assert.equal(bytesOf('a\u200bb').length, bytesOf('ab').length + 3);
  assert.equal(bytesOf('\ufeffabc').length, bytesOf('abc').length + 3);
  assert.equal(bytesOf('\u2764\ufe0f').length, bytesOf('\u2764').length + 3);
  assert.equal(bytesOf('\u{1f468}\u200d\u{1f469}\u200d\u{1f467}').length, bytesOf('\u{1f468}\u{1f469}\u{1f467}').length + 6);
  assert.equal(bytesOf('A').length, 1);
  assert.equal(bytesOf('\uff21').length, 3);
  assert.equal(bytesOf('a').length, 1);
  assert.equal(bytesOf('\u0430').length, 2);
  assert.deepEqual([bytesOf('a b').length, bytesOf('a\u00a0b').length, bytesOf('a\u3000b').length], [3, 4, 5]);
  assert.deepEqual([bytesOf('a\nb').length, bytesOf('a\r\nb').length, bytesOf('a\rb').length], [3, 4, 3]);
  assert.notEqual(sha256(bytesOf('abc')), sha256(bytesOf('abc\n')));
  assert.equal(sha256(bytesOf('')), sha256(Buffer.alloc(0)));
  const family = input.encodeText('\u{1f468}\u200d\u{1f469}\u200d\u{1f467}');
  assert.deepEqual([family.stats.utf16Units, family.stats.codePoints, family.stats.byteCount], [8, 5, 18]);
  assert.deepEqual(family.chars.map(c => c.cls), ['text', 'zwj', 'text', 'zwj', 'text']);
  assert.deepEqual(family.chars.map(c => c.length), [4, 3, 4, 3, 4]);
});

test('A lone surrogate and U+FFFD give the same bytes; the lone surrogate is detected before encoding', () => {
  const lone = input.encodeText('a\ud800b');
  const replacement = input.encodeText('a\ufffdb');
  assert.equal(hex(lone.bytes), hex(replacement.bytes));
  assert.equal(sha256(lone.bytes), sha256(replacement.bytes));
  assert.equal(sha256(lone.bytes), sha256(utf8('a\ud800b')));
  assert.equal(lone.stats.loneSurrogates, 1);
  assert.equal(replacement.stats.loneSurrogates, 0);
  assert.deepEqual(lone.chars[1], { index: 1, cp: 0xd800, char: '\ud800', start: 1, length: 3, cls: 'lone-surrogate' });
  assert.equal(replacement.chars[1].cls, 'replacement');
  assert.equal(lone.chars[2].start, 4);
  assert.equal(input.encodeText('\u{10000}\ud800').stats.loneSurrogates, 1);
  assert.equal(input.encodeText('\udc00\ud800').stats.loneSurrogates, 2);
  assert.equal(input.encodeText('\u{1f600}').stats.loneSurrogates, 0);
});

test('Newline statistics: CRLF pairs first, then lone LF and lone CR; trailing newline from the final string', () => {
  const cases = [
    ['a\r\nb', { lf: 0, cr: 0, crlf: 1, trailingNewline: 'none' }, 4],
    ['a\nb', { lf: 1, cr: 0, crlf: 0, trailingNewline: 'none' }, 3],
    ['a\rb', { lf: 0, cr: 1, crlf: 0, trailingNewline: 'none' }, 3],
    ['abc\n', { lf: 1, cr: 0, crlf: 0, trailingNewline: 'lf' }, 4],
    ['abc\r\n', { lf: 0, cr: 0, crlf: 1, trailingNewline: 'crlf' }, 5],
    ['abc\r', { lf: 0, cr: 1, crlf: 0, trailingNewline: 'none' }, 4],
    ['\r\r\n', { lf: 0, cr: 1, crlf: 1, trailingNewline: 'crlf' }, 3],
    ['a\n\rb', { lf: 1, cr: 1, crlf: 0, trailingNewline: 'none' }, 4],
    ['', { lf: 0, cr: 0, crlf: 0, trailingNewline: 'none' }, 0]
  ];
  for (const [text, expected, byteCount] of cases) {
    const { stats, chars } = input.encodeText(text);
    const { lf, cr, crlf, trailingNewline } = stats;
    assert.deepEqual({ lf, cr, crlf, trailingNewline }, expected, JSON.stringify(text));
    assert.equal(stats.byteCount, byteCount);
    assert.equal(chars.filter(c => c.cls === 'lf').length, lf + crlf);
    assert.equal(chars.filter(c => c.cls === 'cr').length, cr + crlf);
  }
});

test('newline: "crlf" expands LF to CRLF but never touches an LF that already follows CR', () => {
  const expanded = input.encodeText('a\nb', { newline: 'crlf' });
  assert.equal(expanded.text, 'a\r\nb');
  assert.equal(hex(expanded.bytes), hex(utf8('a\r\nb')));
  assert.deepEqual([expanded.stats.lf, expanded.stats.crlf, expanded.stats.cr], [0, 1, 0]);
  const kept = input.encodeText('a\r\nb', { newline: 'crlf' });
  assert.equal(kept.text, 'a\r\nb');
  assert.equal(kept.stats.crlf, 1);
  assert.equal(input.encodeText('a\r\n\nb', { newline: 'crlf' }).text, 'a\r\n\r\nb');
  assert.equal(input.encodeText('a\rb', { newline: 'crlf' }).text, 'a\rb');
  assert.equal(input.encodeText('a\nb', { newline: 'lf' }).text, 'a\nb');
  assert.equal(input.encodeText('a\r\nb').text, 'a\r\nb');
});

test('trailingNewline adds one newline of the selected kind even when the text already ends with one', () => {
  const lf = input.encodeText('abc', { trailingNewline: true });
  assert.equal(lf.text, 'abc\n');
  assert.equal(hex(lf.bytes), hex(utf8('abc\n')));
  assert.equal(lf.stats.trailingNewline, 'lf');
  const crlf = input.encodeText('abc', { newline: 'crlf', trailingNewline: true });
  assert.equal(crlf.text, 'abc\r\n');
  assert.equal(crlf.stats.trailingNewline, 'crlf');
  const doubled = input.encodeText('abc\n', { trailingNewline: true });
  assert.equal(doubled.text, 'abc\n\n');
  assert.equal(doubled.stats.lf, 2);
  const doubledCrlf = input.encodeText('abc\n', { newline: 'crlf', trailingNewline: true });
  assert.equal(doubledCrlf.text, 'abc\r\n\r\n');
  assert.equal(doubledCrlf.stats.crlf, 2);
  assert.equal(input.encodeText('abc', { trailingNewline: false }).text, 'abc');
});

test('bom prepends U+FEFF, which shows up as three bytes and shifts every offset', () => {
  const result = input.encodeText('abc', { bom: true });
  assert.equal(result.text, '\ufeffabc');
  assert.equal(hex(result.bytes), hex(utf8('\ufeffabc')));
  assert.equal(result.stats.bom, true);
  assert.deepEqual([result.stats.codePoints, result.stats.utf16Units, result.stats.byteCount], [4, 4, 6]);
  assert.deepEqual(result.chars[0], { index: 0, cp: 0xfeff, char: '\ufeff', start: 0, length: 3, cls: 'bom' });
  assert.equal(result.chars[1].start, 3);
  assert.equal(input.encodeText('abc').stats.bom, false);
  assert.equal(input.encodeText('\ufeffabc').stats.bom, true);
  const all = input.encodeText('a\nb', { newline: 'crlf', trailingNewline: true, bom: true });
  assert.equal(all.text, '\ufeffa\r\nb\r\n');
  assert.equal(hex(all.bytes), hex(utf8('\ufeffa\r\nb\r\n')));
});

test('Day117 seed: three header lines joined by LF are 55 bytes and hash to the chain vector seed', () => {
  const seed = input.encodeText(seedText);
  assert.equal(seed.stats.byteCount, 55);
  assert.equal(seed.stats.byteCount, Buffer.byteLength(seedText, 'utf8'));
  assert.equal(sha256(seed.bytes), access.seed);
  assert.equal(sha256(utf8(seedText)), access.seed);
  assert.deepEqual([seed.stats.lf, seed.stats.crlf, seed.stats.cr, seed.stats.trailingNewline], [2, 0, 0, 'none']);
  const lfOffsets = codePoints(seedText).map((cp, i) => (cp === 0x0a ? i : -1)).filter(i => i >= 0);
  assert.deepEqual(seed.chars.filter(c => c.cls === 'lf').map(c => c.start), lfOffsets);
  assert.equal(seed.stats.normalization, 'both');

  const crlf = input.encodeText(seedText, { newline: 'crlf' });
  assert.equal(crlf.stats.byteCount, 57);
  assert.equal(sha256(crlf.bytes), sha256(utf8(access.headers.join('\r\n'))));
  assert.notEqual(sha256(crlf.bytes), access.seed);
  const trailing = input.encodeText(seedText, { trailingNewline: true });
  assert.equal(trailing.stats.byteCount, 56);
  assert.equal(sha256(trailing.bytes), sha256(utf8(seedText + '\n')));
  assert.notEqual(sha256(trailing.bytes), access.seed);
});

test('Day117 rows: the previous hash travels as 64 characters, the separator is byte 64', () => {
  const row1 = input.encodeText(access.seed + '|' + access.rows[0].join(','));
  assert.equal(row1.stats.byteCount, 87);
  assert.equal(sha256(row1.bytes), access.hashes[0]);
  assert.deepEqual([row1.bytes[0], row1.bytes[1], row1.bytes[64]], [0x37, 0x62, 0x7c]);
  assert.equal(hex(row1.bytes.subarray(0, 2)), hex(utf8(access.seed.slice(0, 2))));
  const trailer = input.encodeText(access.hashes[access.hashes.length - 1] + '|rows=' + access.rows.length);
  assert.equal(trailer.stats.byteCount, 71);
  assert.equal(sha256(trailer.bytes), access.trailer);
  let previous = access.seed;
  access.rows.forEach((fields, i) => {
    const row = input.encodeText(previous + '|' + fields.join(','));
    assert.equal(sha256(row.bytes), access.hashes[i]);
    previous = access.hashes[i];
  });
});

const ok = text => {
  const result = input.parseHex(text);
  assert.equal(result.ok, true, JSON.stringify(text) + ' ' + JSON.stringify(result.error));
  return result;
};
const fail = text => {
  const result = input.parseHex(text);
  assert.equal(result.ok, false, JSON.stringify(text));
  return result;
};
const NO_REMOVAL = { prefix0x: 0, prefixBackslashX: 0, separators: 0, whitespace: 0, uppercase: 0 };

test('parseHex accepts the formats of the memo table and reports what it removed', () => {
  const plain = ok('7b7b');
  assert.equal(hex(plain.bytes), '7b7b');
  assert.equal(plain.normalized, '7b 7b');
  assert.deepEqual(plain.removed, NO_REMOVAL);
  assert.deepEqual(plain.warnings, []);
  assert.deepEqual(plain.tokens, [{ start: 0, end: 4, raw: '7b7b', prefix: '', hex: '7b7b', count: 2 }]);

  const spaced = ok('7b 7b');
  assert.equal(hex(spaced.bytes), '7b7b');
  assert.deepEqual(spaced.removed, { ...NO_REMOVAL, whitespace: 1 });
  assert.equal(spaced.tokens.length, 2);
  assert.deepEqual(spaced.tokens.map(t => [t.start, t.end]), [[0, 2], [3, 5]]);

  const mixedCase = ok('7B7b');
  assert.equal(hex(mixedCase.bytes), '7b7b');
  assert.equal(mixedCase.normalized, '7b 7b');
  assert.deepEqual(mixedCase.removed, { ...NO_REMOVAL, uppercase: 1 });

  for (const separator of [':', ',', '-', ';']) {
    const result = ok('7b' + separator + '7b');
    assert.equal(hex(result.bytes), '7b7b', separator);
    assert.deepEqual(result.removed, { ...NO_REMOVAL, separators: 1 });
  }

  const prefixed = ok('0x7b');
  assert.equal(hex(prefixed.bytes), '7b');
  assert.deepEqual(prefixed.removed, { ...NO_REMOVAL, prefix0x: 1 });
  assert.deepEqual(prefixed.tokens, [{ start: 0, end: 4, raw: '0x7b', prefix: '0x', hex: '7b', count: 1 }]);
  assert.deepEqual(ok('0X7B').removed, { ...NO_REMOVAL, prefix0x: 1, uppercase: 1 });

  const cArray = ok('{0x7b, 0x7b}');
  assert.equal(hex(cArray.bytes), '7b7b');
  assert.deepEqual(cArray.removed, { ...NO_REMOVAL, prefix0x: 2, separators: 3, whitespace: 1 });
  assert.equal(hex(ok('[0x7b, 0x7b]').bytes), '7b7b');

  const lines = ok('7b\n7b');
  assert.equal(hex(lines.bytes), '7b7b');
  assert.deepEqual(lines.removed, { ...NO_REMOVAL, whitespace: 1 });
  assert.equal(hex(ok('7b\r\n7b\r\n').bytes), '7b7b');

  const python = ok('\\x7b \\x7b');
  assert.equal(hex(python.bytes), '7b7b');
  assert.deepEqual(python.removed, { ...NO_REMOVAL, prefixBackslashX: 2, whitespace: 1 });

  const abc = ok('61 62 63');
  assert.equal(hex(abc.bytes), hex(utf8('abc')));
  assert.equal(sha256(abc.bytes), sha256(utf8('abc')));
  assert.equal(hex(ok('ef bb bf 61 62 63').bytes), hex(utf8('\ufeffabc')));
});

test('parseHex: empty or whitespace-only input is zero bytes', () => {
  for (const text of ['', ' ', ' \n\t\r', '\u000b\u000c', ', ;']) {
    const result = ok(text);
    assert.equal(result.bytes.length, 0, JSON.stringify(text));
    assert.equal(result.normalized, '');
    assert.deepEqual(result.tokens, []);
    assert.deepEqual(result.warnings, []);
  }
  assert.deepEqual(ok(' \n\t').removed, { ...NO_REMOVAL, whitespace: 3 });
  assert.equal(sha256(ok('').bytes), sha256(Buffer.alloc(0)));
  assert.equal(ok(null).bytes.length, 0);
});

test('Text "7b" is two bytes, hex 7b is one byte and the same byte as the character "{"', () => {
  const asText = input.encodeText('7b');
  const asHex = ok('7b');
  const brace = input.encodeText('{');
  assert.equal(asText.bytes.length, 2);
  assert.equal(asHex.bytes.length, 1);
  assert.equal(hex(asHex.bytes), hex(brace.bytes));
  assert.equal(sha256(asHex.bytes), sha256(brace.bytes));
  assert.notEqual(sha256(asHex.bytes), sha256(asText.bytes));
  assert.equal(hex(asText.bytes), hex(utf8('7b')));
});

test('parseHex rejects odd-length tokens without joining across whitespace or padding a nibble', () => {
  const odd = fail('7b7');
  assert.deepEqual(odd.error, { code: 'odd-length', position: 2, line: 1, column: 3, char: '7', codePoint: 0x37, name: 'U+0037', token: '7b7', tokenStart: 0 });
  assert.deepEqual(odd.warnings, []);
  const split = fail('7 b');
  assert.equal(split.error.code, 'odd-length');
  assert.deepEqual([split.error.position, split.error.char, split.error.token], [0, '7', '7']);
  assert.deepEqual([fail('7').error.code, fail('7').error.position], ['odd-length', 0]);
  const late = fail('7b 7b 7');
  assert.deepEqual([late.error.code, late.error.position, late.error.column], ['odd-length', 6, 7]);
  const prefixedOdd = fail('0x7');
  assert.deepEqual([prefixedOdd.error.code, prefixedOdd.error.position, prefixedOdd.error.char], ['odd-length', 2, '7']);
});

test('parseHex rejects non-hex characters with position, line, column and the character name', () => {
  const garbage = fail('7bzz7b');
  assert.deepEqual(garbage.error, { code: 'invalid-char', position: 2, line: 1, column: 3, char: 'z', codePoint: 0x7a, name: 'U+007A', token: '7bzz7b', tokenStart: 0 });
  const named = [
    ['7b\u30007b', 'U+3000 IDEOGRAPHIC SPACE'],
    ['7b\u00a07b', 'U+00A0 NO-BREAK SPACE'],
    ['7b\ufeff7b', 'U+FEFF ZERO WIDTH NO-BREAK SPACE'],
    ['7b\u200b7b', 'U+200B ZERO WIDTH SPACE'],
    ['7b\uff17b', 'U+FF17 FULLWIDTH DIGIT SEVEN'],
    ['7b\uff10\uff10', 'U+FF10 FULLWIDTH DIGIT ZERO']
  ];
  for (const [text, name] of named) {
    const result = fail(text);
    assert.equal(result.error.code, 'invalid-char', text);
    assert.equal(result.error.position, 2, text);
    assert.equal(result.error.column, 3, text);
    assert.equal(result.error.char, text[2], text);
    assert.equal(result.error.codePoint, text.codePointAt(2), text);
    assert.equal(result.error.name, name, text);
  }
  const midPrefix = fail('0x7b0x7b');
  assert.deepEqual([midPrefix.error.code, midPrefix.error.position, midPrefix.error.char], ['invalid-char', 5, 'x']);
  const barePrefix = fail('0x');
  assert.deepEqual([barePrefix.error.code, barePrefix.error.position, barePrefix.error.char], ['invalid-char', 1, 'x']);
  const joinedBackslash = ok('\\x7b\\x7b');
  assert.equal(hex(joinedBackslash.bytes), '7b7b');
  assert.deepEqual(joinedBackslash.removed, { ...NO_REMOVAL, prefixBackslashX: 2 });
  assert.deepEqual(joinedBackslash.tokens.map(t => [t.start, t.end, t.hex]), [[0, 4, '7b'], [4, 8, '7b']]);
  assert.equal(hex(ok('7b\\x7b').bytes), '7b7b');
  const trailingBackslash = fail('\\x7b\\');
  assert.deepEqual([trailingBackslash.error.code, trailingBackslash.error.position, trailingBackslash.error.char, trailingBackslash.error.name],
    ['invalid-char', 4, '\\', 'U+005C']);
  const astral = fail('\u{1f600}');
  assert.deepEqual([astral.error.code, astral.error.position, astral.error.char, astral.error.codePoint, astral.error.name],
    ['invalid-char', 0, '\u{1f600}', 0x1f600, 'U+1F600']);
  const trailingGarbage = fail('7b7b g');
  assert.deepEqual([trailingGarbage.error.position, trailingGarbage.error.column, trailingGarbage.error.char], [5, 6, 'g']);
  assert.equal(fail('7b *-').error.char, '*');
});

test('parseHex counts lines by CRLF, LF or CR and columns from 1', () => {
  const lf = fail('7b\n7b\nzz');
  assert.deepEqual([lf.error.position, lf.error.line, lf.error.column], [6, 3, 1]);
  const crlf = fail('7b\r\n7b\r\n7bz');
  assert.deepEqual([crlf.error.position, crlf.error.line, crlf.error.column], [10, 3, 3]);
  const cr = fail('7b\r7b\rz');
  assert.deepEqual([cr.error.position, cr.error.line, cr.error.column], [6, 3, 1]);
  const second = fail('7b 7b\n  7b 7b7');
  assert.deepEqual([second.error.code, second.error.position, second.error.line, second.error.column], ['odd-length', 13, 2, 8]);
});

test('parseHex warns about dump-like input (offset column) whether it parses or not', () => {
  const xxd = '00000000: 6162 6364 6566 6768 696a 6b6c 6d6e 6f70  abcdefghijklmnop\n' +
    '00000010: 7172 7374 7576 7778 797a                 qrstuvwxyz\n';
  const failed = fail(xxd);
  assert.deepEqual(failed.warnings, ['dump-like']);
  assert.equal(failed.error.code, 'invalid-char');
  assert.equal(failed.error.char, 'g');
  assert.equal(failed.error.position, xxd.indexOf('g'));
  assert.equal(failed.error.line, 1);
  const hexdump = '00000000  61 62 63                                          |abc|\n';
  assert.deepEqual([fail(hexdump).warnings, fail(hexdump).error.char], [['dump-like'], '|']);
  const od = '0000000 61 62 63\n0000003\n';
  assert.deepEqual([fail(od).warnings, fail(od).error.code], [['dump-like'], 'odd-length']);
  const trap = ok('00000000: 6162  ab\n');
  assert.deepEqual(trap.warnings, ['dump-like']);
  assert.equal(hex(trap.bytes), '000000006162ab');
  assert.deepEqual(ok('7b7b').warnings, []);
  assert.deepEqual(ok('deadbeef cafebabe').warnings, ['dump-like']);
  assert.deepEqual(ok('61 62 63 64 65 66 67 68').warnings, []);
});

test('parseHex warns when the whole input is one 64-digit token (a digest pasted as bytes)', () => {
  const digest = sha256(utf8('abc'));
  const pasted = ok(digest);
  assert.deepEqual(pasted.warnings, ['hash-like']);
  assert.equal(pasted.bytes.length, 32);
  assert.equal(hex(pasted.bytes), digest);
  const upper = ok(digest.toUpperCase());
  assert.deepEqual(upper.warnings, ['hash-like']);
  assert.equal(upper.removed.uppercase, digest.replace(/[^a-f]/g, '').length);
  assert.equal(hex(upper.bytes), digest);
  const sumLine = ok(digest + '  -');
  assert.deepEqual(sumLine.warnings, ['hash-like']);
  assert.deepEqual(sumLine.removed, { ...NO_REMOVAL, separators: 1, whitespace: 2 });
  assert.deepEqual(ok(digest.slice(0, 32) + ' ' + digest.slice(32)).warnings, []);
  assert.deepEqual(ok('ab'.repeat(33)).warnings, []);
  assert.deepEqual(ok('ab'.repeat(31)).warnings, []);
  assert.notEqual(sha256(pasted.bytes), sha256(utf8(digest)));
});

test('classifyCodePoint names the invisible characters and falls back by Unicode category', () => {
  const expected = [
    [0x61, 'text'], [0x0a, 'lf'], [0x0d, 'cr'], [0x09, 'tab'], [0x20, 'space'], [0xa0, 'nbsp'],
    [0x3000, 'ideographic-space'], [0x200b, 'zwsp'], [0x200d, 'zwj'], [0xfe0f, 'vs16'], [0xfeff, 'bom'],
    [0xfffd, 'replacement'], [0xd800, 'lone-surrogate'], [0xdfff, 'lone-surrogate'],
    [0x00, 'control'], [0x1b, 'control'], [0x7f, 'control'], [0x85, 'control'],
    [0x200c, 'format'], [0xad, 'format'], [0x200e, 'format'],
    [0x2003, 'space'], [0x2028, 'space'], [0x202f, 'space'],
    [0x3042, 'text'], [0x1f600, 'text'], [0xfe0e, 'text'], [0x0301, 'text'], [0xff21, 'text']
  ];
  for (const [cp, cls] of expected) assert.equal(input.classifyCodePoint(cp), cls, cp.toString(16));
  for (const [, cls] of expected) assert.ok(input.CLASSES.includes(cls), cls);
  const chars = input.encodeText('a\tb c\u00a0d\u3000e\u200bf\u200dg\u2764\ufe0fh\ud800i\u0000').chars;
  assert.deepEqual(chars.map(c => c.cls), ['text', 'tab', 'text', 'space', 'text', 'nbsp', 'text', 'ideographic-space',
    'text', 'zwsp', 'text', 'zwj', 'text', 'text', 'vs16', 'text', 'lone-surrogate', 'text', 'control']);
});

test('unicodeName gives the name of the main invisible characters and U+XXXX for the rest', () => {
  assert.equal(input.unicodeName(0x3000), 'U+3000 IDEOGRAPHIC SPACE');
  assert.equal(input.unicodeName(0x09), 'U+0009 CHARACTER TABULATION');
  assert.equal(input.unicodeName(0x20), 'U+0020 SPACE');
  assert.equal(input.unicodeName(0xa0), 'U+00A0 NO-BREAK SPACE');
  assert.equal(input.unicodeName(0xfeff), 'U+FEFF ZERO WIDTH NO-BREAK SPACE');
  assert.equal(input.unicodeName(0x200b), 'U+200B ZERO WIDTH SPACE');
  assert.equal(input.unicodeName(0x200d), 'U+200D ZERO WIDTH JOINER');
  assert.equal(input.unicodeName(0xfe0f), 'U+FE0F VARIATION SELECTOR-16');
  assert.equal(input.unicodeName(0xfffd), 'U+FFFD REPLACEMENT CHARACTER');
  assert.equal(input.unicodeName(0x0a), 'U+000A LINE FEED');
  assert.equal(input.unicodeName(0x0d), 'U+000D CARRIAGE RETURN');
  assert.equal(input.unicodeName(0xff10), 'U+FF10 FULLWIDTH DIGIT ZERO');
  assert.equal(input.unicodeName(0xff19), 'U+FF19 FULLWIDTH DIGIT NINE');
  assert.equal(input.unicodeName(0x61), 'U+0061');
  assert.equal(input.unicodeName(0x00), 'U+0000');
  assert.equal(input.unicodeName(0x200c), 'U+200C');
  assert.equal(input.unicodeName(0x1f600), 'U+1F600');
  assert.equal(input.unicodeName(0xd800), 'U+D800');
});

test('normalizationStatus tells NFC from NFD without changing the text', () => {
  assert.equal(input.normalizationStatus('\u304c'), 'nfc');
  assert.equal(input.normalizationStatus('\u304b\u3099'), 'nfd');
  assert.equal(input.normalizationStatus('\u00e9'), 'nfc');
  assert.equal(input.normalizationStatus('e\u0301'), 'nfd');
  assert.equal(input.normalizationStatus('abc'), 'both');
  assert.equal(input.normalizationStatus(''), 'both');
  assert.equal(input.normalizationStatus('\u304b\u3099\u304c'), 'neither');
  assert.equal(input.normalizationStatus('a\ud800b'), 'both');
  assert.equal(input.encodeText('\u304c').stats.normalization, 'nfc');
  assert.equal(input.encodeText('\u304b\u3099').stats.normalization, 'nfd');
  assert.equal(input.encodeText('abc', { bom: true, trailingNewline: true }).stats.normalization, 'both');
  assert.equal(input.encodeText('\u304c').text, '\u304c');
  assert.equal(input.encodeText('\u304b\u3099').text, '\u304b\u3099');
});

test('parseFragment reads v/m/in/at/r/l/d and the Day117 style #text= and #hex=', () => {
  const full = input.parseFragment('#v=1&m=t&in=abc%0A&at=b1.r51&r=hex&l=ja');
  assert.deepEqual(full, { text: 'abc\n', hex: null, at: 'b1.r51', r: 'hex', l: 'ja', m: 't', d: null, v: '1', error: false });
  const hexMode = input.parseFragment('v=1&m=x&in=7b%207b&l=en&d=ab');
  assert.deepEqual(hexMode, { text: null, hex: '7b 7b', at: null, r: null, l: 'en', m: 'x', d: 'ab', v: '1', error: false });
  const legacyText = input.parseFragment('#text=' + encodeURIComponent(seedText));
  assert.equal(legacyText.text, seedText);
  assert.equal(legacyText.m, 't');
  assert.equal(input.parseFragment('#text=%23%20kind%3Dfictional-access%0A%23%20started%3D09%3A00%0A%23%20format%3Dhctt%2F1').text, seedText);
  const legacyHex = input.parseFragment('#hex=7b7b');
  assert.deepEqual([legacyHex.hex, legacyHex.text, legacyHex.m], ['7b7b', null, 'x']);
  assert.equal(input.parseFragment('#foo=bar&in=x').text, 'x');
  assert.equal(input.parseFragment('#foo=bar&in=x').m, 't');
  for (const empty of ['', '#', '#&&', null]) {
    assert.deepEqual(input.parseFragment(empty), { text: null, hex: null, at: null, r: null, l: null, m: null, d: null, v: null, error: false });
  }
  assert.equal(input.parseFragment('#in=a%3Db%3Dc').text, 'a=b=c');
  assert.equal(input.parseFragment('#in=').text, '');
});

test('parseFragment keeps CR and + as they are, and drops only the element that fails to decode', () => {
  const cr = input.parseFragment('#v=1&m=t&in=a%0D%0Ab');
  assert.equal(cr.text, 'a\r\nb');
  assert.equal(input.encodeText(cr.text).stats.crlf, 1);
  assert.equal(input.parseFragment('#v=1&m=t&in=a%2Bb+c').text, 'a+b+c');
  const broken = input.parseFragment('#v=1&m=t&in=%E3%81&at=b1.r0');
  assert.deepEqual([broken.error, broken.text, broken.hex, broken.at, broken.v], [true, null, null, 'b1.r0', '1']);
  const brokenLegacy = input.parseFragment('#text=%ZZ');
  assert.deepEqual([brokenLegacy.error, brokenLegacy.text], [true, null]);
  const brokenKey = input.parseFragment('#%E3=1&in=ok');
  assert.deepEqual([brokenKey.error, brokenKey.text], [true, 'ok']);
  assert.equal(input.parseFragment('#in=%EF%BF%BD').text, '\ufffd');
});

test('buildFragment writes keys in the order v, m, in, at, r, l, d and percent-encodes every value', () => {
  const link = input.buildFragment({ text: 'abc\n', at: 'b1.r51', r: 'hex', l: 'ja' });
  assert.equal(link.fragment, '#v=1&m=t&in=abc%0A&at=b1.r51&r=hex&l=ja');
  assert.equal(link.error, false);
  assert.deepEqual(link.omitted, []);
  assert.equal(String(link), link.fragment);
  assert.equal('' + link, link.fragment);
  assert.equal(`${link}`, link.fragment);
  assert.equal(input.buildFragment({ hex: '7b 7b', d: 'ab', l: 'en' }).fragment, '#v=1&m=x&in=7b%207b&l=en&d=ab');
  assert.equal(input.buildFragment({ text: 'a\r\nb' }).fragment, '#v=1&m=t&in=a%0D%0Ab');
  assert.equal(input.buildFragment({ text: 'a+b c' }).fragment, '#v=1&m=t&in=a%2Bb%20c');
  assert.equal(input.buildFragment({ text: seedText }).fragment, '#v=1&m=t&in=' + encodeURIComponent(seedText));
  assert.equal(input.buildFragment({ text: '' }).fragment, '#v=1&m=t&in=');
  assert.equal(input.buildFragment({}).fragment, '#v=1');
  assert.equal(input.buildFragment({ m: 'x', in: '7b', at: 'out' }).fragment, '#v=1&m=x&in=7b&at=out');
  assert.equal(input.buildFragment({ text: 'a', v: 2 }).fragment, '#v=2&m=t&in=a');
});

test('buildFragment leaves out a value with a lone surrogate and sets error', () => {
  const link = input.buildFragment({ text: 'a\ud800b', at: 'out' });
  assert.equal(link.error, true);
  assert.deepEqual(link.omitted, ['in']);
  assert.equal(link.fragment, '#v=1&m=t&at=out');
  assert.equal(input.parseFragment(link.fragment).text, null);
  const compare = input.buildFragment({ text: 'abc', d: '\udc00' });
  assert.deepEqual([compare.error, compare.omitted, compare.fragment], [true, ['d'], '#v=1&m=t&in=abc']);
  assert.equal(input.buildFragment({ text: '\u{1f600}' }).error, false);
});

test('Fragment round trip restores the text and the hex exactly', () => {
  const samples = ['', 'abc', '# kind=a&b=c#d', 'a\r\nb', 'a\rb', 'a\nb\n', '\u304b\u3099', '\u{1f600}', '%41 +', '\ufeffabc',
    'a\u3000b', '\u0000', seedText, access.seed + '|' + access.rows[0].join(',')];
  for (const sample of samples) {
    const asText = input.buildFragment({ text: sample, at: 'b1.pad', r: 'bin', l: 'en', d: 'x' });
    assert.equal(asText.error, false, JSON.stringify(sample));
    const parsedText = input.parseFragment(asText.fragment);
    assert.equal(parsedText.text, sample, JSON.stringify(sample));
    assert.deepEqual([parsedText.hex, parsedText.at, parsedText.r, parsedText.l, parsedText.d, parsedText.m], [null, 'b1.pad', 'bin', 'en', 'x', 't']);
    assert.equal(sha256(input.encodeText(parsedText.text).bytes), sha256(utf8(sample)));
    const asHex = input.buildFragment({ hex: sample });
    const parsedHex = input.parseFragment(asHex.fragment);
    assert.deepEqual([parsedHex.hex, parsedHex.text, parsedHex.m], [sample, null, 'x']);
  }
  assert.doesNotMatch(input.buildFragment({ text: 'a\nb c' }).fragment, /[\s]/);
});

test('sha256sumLine writes the digest in lowercase followed by two spaces and a dash', () => {
  const digest = sha256(utf8('abc'));
  const line = input.sha256sumLine(digest);
  assert.equal(line, digest + '  -');
  assert.equal(input.sha256sumLine(digest.toUpperCase()), line);
  assert.match(line, /^[0-9a-f]{64}  -$/);
  const back = input.parseHex(line);
  assert.equal(back.ok, true);
  assert.equal(hex(back.bytes), digest);
  assert.deepEqual(back.warnings, ['hash-like']);
});

test('input-core.js is a frozen UMD module without Japanese text or forbidden APIs', () => {
  assert.ok(Object.isFrozen(input));
  const source = fs.readFileSync(path.join(__dirname, '..', 'input-core.js'), 'utf8');
  assert.doesNotMatch(source, /[\u3040-\u30ff\u3400-\u9fff\uff00-\uffef]/);
  assert.doesNotMatch(source, /innerHTML|outerHTML|insertAdjacentHTML|\beval\s*\(|\bfetch\s*\(|XMLHttpRequest|WebSocket|Worker\s*\(|\bdocument\b|\bwindow\b|localStorage/);
  assert.match(source, /root\.SHA256ByteInput = factory\(\)/);
  assert.deepEqual(Object.keys(input).sort(), ['CLASSES', 'FRAGMENT_KEYS', 'buildFragment', 'classifyCodePoint', 'encodeText', 'hexBytes',
    'normalizationStatus', 'parseFragment', 'parseHex', 'sha256sumLine', 'unicodeName']);
  assert.deepEqual([...input.FRAGMENT_KEYS], ['v', 'm', 'in', 'at', 'r', 'l', 'd']);
});
